// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;

    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 seedAmount, address recipient) public {
        seedAmount = bound(seedAmount, 0, 10 ether);

        vm.deal(address(this), seedAmount + 1 ether);

        if (seedAmount > 0) {
            (bool sent, ) = address(c).call{value: seedAmount}("");
            require(sent);
        }

        bool ok;
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && address(c).balance == 0);
    }
}
